    if not grid:
        return 0
    rows = len(grid)
    # Build visited matching each row's actual length
    visited = [ [False]*len(row) for row in grid ]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            x,y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # Explore four directions
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows:
                    # Check column bounds for the neighbor row
                    if 0 <= ny < len(grid[nx]) and not visited[nx][ny] and grid[nx][ny] == 1:
                        stack.append((nx,ny))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i,j)
                count += 1
    return count

