def solve(matrix):
    # Spiral order using layer removal; works for rectangular and jagged matrices.
    res = []
    # Make a copy to avoid mutating input (optional)
    mat = [list(row) for row in matrix]
    while mat:
        # top row
        res.extend(mat.pop(0))
        # right column
        for row in mat:
            if row:
                res.append(row.pop())
        # bottom row (if any)
        if mat:
            res.extend(reversed(mat.pop()))
        # left column (if any)
        for row in reversed(mat):
            if row:
                res.append(row.pop(0))
    return res

