def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Patience sorting algorithm O(n log n).
    """
    import bisect
    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

