def solve(nums):
    # Longest increasing subsequence length using patience sorting
    if not nums:
        return 0
    tails = []
    for x in nums:
        # binary search for the leftmost tail >= x
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(tails)

